function latinFromHebrew(s){const m={'א':'','ב':'b','ג':'g','ד':'d','ה':'h','ז':'z','ח':'kh','ט':'t','כ':'k','ך':'k','ל':'l','מ':'m','ם':'m','נ':'n','ן':'n','ס':'s','ע':'','פ':'p','ף':'f','צ':'ts','ץ':'ts','ק':'k','ר':'r','ש':'sh','ת':'t'};const vow={'ַ':'a','ָ':'a','ֶ':'e','ֵ':'e','ִ':'i','ֹ':'o','ֻ':'u','ֲ':'a','ֱ':'e','ֳ':'o'};const ch=[...s.normalize('NFD')];let out='';for(let i=0;i<ch.length;i++){const c=ch[i],n=ch[i+1];if(vow[c]!==undefined){out+=vow[c];continue}if(/[֑-ׇ]/.test(c))continue;if(c==="'"||c==='׳'){const last=out.slice(-1);if(last==='g')out=out.slice(0,-1)+'j';else if(out.endsWith('ts'))out=out.slice(0,-2)+'ch';else if(last==='t')out+='h';else if(last==='d')out=out.slice(0,-1)+'th';continue}if(c==='ו'){const marks=ch.slice(i+1,i+3).join('');if(marks.includes('ֹ')){out+='o';i++;continue}if(marks.startsWith('ּ')&&!/[ְ-ֻ]/.test(ch[i+2]||'')){out+='u';i++;continue}out+='w';continue}if(c==='י'){const prev=out.slice(-1),hasVowel=/[ְ-ֻ]/.test(n||'');if(!hasVowel&&/[aeiou]/.test(prev)){out+=prev==='i'?'':'i';continue}out+='y';continue}if(c==='פ'){out+=n==='ּ'?'p':'f';continue}if(c==='ש'){out+=n==='ׂ'?'s':'sh';continue}if(c==='ב'){out+=n==='ּ'?'b':'v';continue}out+=m[c]!==undefined?m[c]:c}return out.replace(/\s+/g,' ').trim()}
