function simpleNorm(s){return String(s||'').toLowerCase().normalize('NFC').replace(/[\s.,!?'"׳״\-–—()]/g,'')}
function similarity(a,b){a=simpleNorm(a);b=simpleNorm(b);if(!a||!b)return 0;if(a===b||a.includes(b)||b.includes(a))return 1;const d=Array.from({length:a.length+1},(_,i)=>[i]);for(let j=1;j<=b.length;j++)d[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return 1-d[a.length][b.length]/Math.max(a.length,b.length)}
